-- CoA rotations per specialization, for playerbots_custom_strategy.
--
-- 71 strategies: one combat rotation per specialization plus the Tinker's
-- non-combat set, 2544 rules in total. Generated from the per-specialization
-- guides published by ascensionsidekick.com and checked against the client's
-- Spell.dbc. Credit for the guide data belongs there.
--
-- These rows do nothing on their own. They are applied only when
-- AiPlayerbot.CoaSpecRotations is on; with the setting off, CoA bots run on
-- the runtime classifier alone and never look this table up.
--
-- Re-applicable by design: every block deletes its own strategy first, so a
-- regenerated file replaces what it owns and a partial load is not possible.
-- Per-bot rows (owner != 0) are not touched.
--
-- Do not edit by hand. The generator is tools/rotation_bauen.py in
-- mod-playerbots-coa; the next run overwrites whatever is here.

-- ===== klasse-12-barbarian-ancestry.sql ==================================
-- Barbarian / Ancestry - combat rotation up to level 20.
--
-- Role:      damage  (support)
-- Position:  close
-- Spec id:   3
--
-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::barbarian-ancestry
--
-- STANDARD RESOURCES this rotation spends:
--   Energie: Keg Smash, Keg Smash, Breath of The North, Warband, Splash Zone, Jawbreaker, Maiming Spear, Tavern Brawl!, Clanlord's Totem, Spirit of War, Spirit of Conflict, Spirit of Bloodshed, Enduring Shout, Barbaric Whirl, Break, Spirit of Savagery, Whirling Advance, Brutal Shout, Ancestral Strike
--   These do NOT come from AscensionCustomResourceData.h but from the
--   standard system. Whether the class actually builds them is in
--   no data - only the bar in game shows it.
--   MIND THE TEST TARGET. Generation is read off the spell, not off
--   the damage dealt, so against a training dummy the bar stays at
--   zero and every rule that spends the resource looks broken. On
--   14.09.2026 we read a Reaper bot that way and filed it as a bug;
--   measured on a live server on 17.09.2026, 14 of 57 Reaper bots
--   had runic power, several a full bar.
--   If a rule never fires although it looks affordable: check the
--   bar on the bot against a real target first, do not change the
--   rule.
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'barbarian-ancestry';

