-- ===== klasse-13-witch-doctor-shadowhunting.sql ==========================
-- Witch Doctor / Shadowhunting - combat rotation up to level 20.
--
-- Role:      damage
-- Position:  ranged
-- Spec id:   4   (class default)
--
-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::witch-doctor-shadowhunting
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'witch-doctor-shadowhunting';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Call of Sseratus (hand-checked, from level 27, ID 681222).
--    [cooldown 40s]
--    Keep the pack up. 681222 is an aura (PERIODIC_TRIGGER_SPELL on
--    572899); the cap of four or five sits in the module.
('witch-doctor-shadowhunting', 1, 0, 'coa summon missing>cast::Call of Sseratus!88'),

-- 2. Hex of Malice (hand-checked, from level 4, ID 801693).
--    The jinx layer, only once it has fully expired.
('witch-doctor-shadowhunting', 2, 0, 'debuff missing::Hex of Malice>cast debuff::Hex of Malice!84'),

-- 3. Shadowflare (hand-checked, from level 16, ID 801669).
--    From two enemies on, spread Hex of Malice.
('witch-doctor-shadowhunting', 3, 0, 'light aoe>cast::Shadowflare!80'),

-- 4. Spirit Eclipse (hand-checked, from level 15, ID 801607).
--    [cooldown 10s]
--    Spend banked Spirits. The spell text counts "for each active Spirit",
--    so it pays off from 3 of 5.
('witch-doctor-shadowhunting', 4, 0, 'aura stacks::Spirit,3>cast::Spirit Eclipse!78'),

-- 5. Spirit Glaive (hand-checked, from level 15, ID 806289).
--    [cooldown 20s]
--    Lowers shadow resistance, scales with $RAP*.5. 20s cooldown, which
--    Spirit Volley shortens further.
('witch-doctor-shadowhunting', 5, 0, 'can cast::Spirit Glaive>cast::Spirit Glaive!76'),

-- 6. Veil of Darkness (hand-checked, from level 0, ID 806507).
--    Raises the damage we deal to the target. 90s cooldown.
('witch-doctor-shadowhunting', 6, 0, 'can cast::Veil of Darkness>cast::Veil of Darkness!72'),

-- 7. Mimic Ward (hand-checked, from level 10, ID 707162).
--    [cooldown 60s]
--    Burst window: the ward mirrors Malefic Arrow, Reclamation and Loa's
--    Brew onto the target.
('witch-doctor-shadowhunting', 7, 0, 'can cast::Mimic Ward>cast::Mimic Ward!70'),

-- 8. Frenzied Spirits (hand-checked, from level 59, ID 560748).
--    [cooldown 20s]
--    Spends Spirits, heals for a share of the damage dealt. It targets the
--    caster itself (target type 1), hence cast buff.
('witch-doctor-shadowhunting', 8, 0, 'medium health>cast buff::Frenzied Spirits!66'),

-- 9. Malefic Wrath (hand-checked, from level 1, ID 807037).
--    Becomes Malefic Arrow from level 10. Its 8s cooldown then applies to
--    the trigger as well, because CanCastSpell makes the same swap.
('witch-doctor-shadowhunting', 9, 0, 'can cast::Malefic Wrath>cast::Malefic Wrath!60'),

-- 10. Reclamation (hand-checked, from level 40, ID 572343).
--    THE FILLER. Ranged weapon damage plus nature; every hit banks a Spirit
--    and so pays for Spirit Eclipse.
('witch-doctor-shadowhunting', 10, 0, 'can cast::Reclamation>cast::Reclamation!58'),

-- 11. Spirit Eclipse (hand-checked, from level 15, ID 801607).
