INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Shadow Puppets (guide/dungeon, from level 0, ID 500015).
--    [cooldown 18s]
--    Sidekick Voodoo, dungeon section: Keep your De Other Side stacks alive
--    off Shadow Puppets so your damage stays high, since damage IS the
--    support here, and use Voice of Bwonsamdi as your burst window on pr
('witch-doctor-voodoo', 1, 0, 'medium aoe>cast::Shadow Puppets!88'),

-- 2. Bad Juju (guide/dungeon, from level 0, ID 802087).
--    [cooldown 15s]
--    Sidekick Voodoo, dungeon section: Keep Zalazane's Malice applied to
--    the dangerous add or boss (spread by Bad Juju/Hexfire via Malignant,
--    amplified by Ritual Hexing), and pour AoE into trash to speed clear
('witch-doctor-voodoo', 2, 0, 'medium aoe>cast::Bad Juju!87'),

-- 3. Hex of Malice (guide/playstyle, from level 0, ID 801693).
--    Sidekick Voodoo, playstyle section: You keep the Hex of Malice DoT
--    rolling, with Zalazane's Malice amplifying it and stretching your
--    Jinxes, and chain nukes: Bad Juju, Malefic Wrath, Hexfire
('witch-doctor-voodoo', 3, 0, 'debuff missing::Hex of Malice>cast debuff::Hex of Malice!86'),

-- 4. Shadow Puppets (guide/solo, from level 0, ID 500015).
--    [cooldown 18s]
--    Sidekick Voodoo, solo section: Open at range by seeding Zalazane's
--    Malice on the pull point, then loop: Bad Juju on cooldown (main nuke;
--    it hits extra targets, spreads Zalazane's Malice via Malignant,
('witch-doctor-voodoo', 4, 0, 'can cast::Shadow Puppets>cast::Shadow Puppets!85'),

