-- ===== klasse-17-knight-of-xoroth-defiance.sql ===========================
-- Knight of Xoroth / Defiance - combat rotation up to level 20.
--
-- Role:      tank
-- Position:  close
-- Spec id:   17
--
-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::knight-of-xoroth-defiance
--
-- STANDARD RESOURCES this rotation spends:
--   Wut: Chainwhip, Flames of Xoroth, Chainwhip, Melt, Meatsaw
--   These do NOT come from AscensionCustomResourceData.h but from the
--   standard system. Whether the class actually builds them is in
--   no data - only the bar in game shows it.
--   MIND THE TEST TARGET. Generation is read off the spell, not off
--   the damage dealt, so against a training dummy the bar stays at
--   zero and every rule that spends the resource looks broken. On
--   14.09.2026 we read a Reaper bot that way and filed it as a bug;
--   measured on a live server on 17.09.2026, 14 of 57 Reaper bots
--   had runic power, several a full bar.
--   If a rule never fires although it looks affordable: check the
--   bar on the bot against a real target first, do not change the
--   rule.
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'knight-of-xoroth-defiance';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Flesh Hook (guide/dungeon, from level 0, ID 500020).
--    [cooldown 35s]
--    Sidekick Defiance, dungeon section: Pull: open with Flesh Hook or
--    Chains of Xoroth to gather the pack onto you
('knight-of-xoroth-defiance', 1, 0, 'medium aoe>cast melee::Flesh Hook!88'),

-- 2. Chainwhip (guide/dungeon, from level 0, ID 800081).
--    [costs 100 Wut, cooldown 20s]
--    Sidekick Defiance, dungeon section: Shieldgore establishes threat
--    immediately, and Demolisher lets Flesh Hook/Chainwhip taunt loose adds
('knight-of-xoroth-defiance', 2, 0, 'medium aoe>cast melee::Chainwhip!87'),

-- 3. Call: Hellfire Imp (guide/dungeon, from level 0, ID 804883).
--    [cooldown 10s]
--    Sidekick Defiance, dungeon section: Keep Call: Hellfire Imp on
--    cooldown to stack imps for their per-imp mitigation and threat
('knight-of-xoroth-defiance', 3, 0, 'medium aoe>cast melee::Call: Hellfire Imp!86'),

-- 4. Suffuse (guide/solo, from level 0, ID 801063).
--    Sidekick Defiance, solo section: Dump Demonfire into Suffuse liberally
--    to stay topped while leveling; self-sustain beats banking for burst
--    when soloing
('knight-of-xoroth-defiance', 4, 0, 'medium health>cast heal::Suffuse!85'),

-- 5. Flesh Hook (guide/solo, from level 0, ID 500020).
--    [cooldown 35s]
--    Sidekick Defiance, solo section: Open by engaging with Flesh Hook
--    (pulls the enemy to you) or Chains of Xoroth, then apply Curse of
--    Xoroth for the DoT, which also primes your next Shieldgore's Black
--    Shie
('knight-of-xoroth-defiance', 5, 0, 'can cast::Flesh Hook>cast melee::Flesh Hook!84'),

-- 6. Call: Hellfire Imp (guide/solo, from level 0, ID 804883).
--    [cooldown 10s]
--    Sidekick Defiance, solo section: Settle into the loop from there:
--    Shieldgore on cooldown (main threat/damage + 2 Demonfire), Call:
--    Hellfire Imp on cooldown for the free rage and an extra body soaking
--    hit
('knight-of-xoroth-defiance', 6, 0, 'can cast::Call: Hellfire Imp>cast melee::Call: Hellfire Imp!83'),

-- 7. Flames of Xoroth (guide/solo, from level 0, ID 801059).
--    [costs 150 Wut]
--    Sidekick Defiance, solo section: Settle into the loop from there:
--    Shieldgore on cooldown (main threat/damage + 2 Demonfire), Call:
--    Hellfire Imp on cooldown for the free rage and an extra body soaking
--    hit
('knight-of-xoroth-defiance', 7, 0, 'can cast::Flames of Xoroth>cast melee::Flames of Xoroth!82'),

-- 8. Snarl (Spell.dbc/taunt, from level 0, ID 800169).
--    [cooldown 8s]
--    Taunt per Spell.dbc (effect 114 / aura 11); a tank takes attention
--    back before it keeps swinging.
('knight-of-xoroth-defiance', 8, 0, 'lose aggro>cast melee::Snarl!94'),

