-- ===== klasse-17-knight-of-xoroth-hellfire.sql ===========================
-- Knight of Xoroth / Hellfire - combat rotation up to level 20.
--
-- Role:      damage
-- Position:  close
-- Spec id:   16
--
-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::knight-of-xoroth-hellfire
--
-- STANDARD RESOURCES this rotation spends:
--   Wut: Infernal Strike, Flames of Xoroth, Hellmaw, Hellmaw, Infernal Strike, Flames of Xoroth, Chainwhip, Hellstorm, Doom, Seeking Flame, Melt, Meatsaw
--   These do NOT come from AscensionCustomResourceData.h but from the
--   standard system. Whether the class actually builds them is in
--   no data - only the bar in game shows it.
--   MIND THE TEST TARGET. Generation is read off the spell, not off
--   the damage dealt, so against a training dummy the bar stays at
--   zero and every rule that spends the resource looks broken. On
--   14.09.2026 we read a Reaper bot that way and filed it as a bug;
--   measured on a live server on 17.09.2026, 14 of 57 Reaper bots
--   had runic power, several a full bar.
--   If a rule never fires although it looks affordable: check the
--   bar on the bot against a real target first, do not change the
--   rule.
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'knight-of-xoroth-hellfire';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Infernal Strike (guide/dungeon, from level 0, ID 801016).
--    [costs 400 Wut]
--    Sidekick Hellfire, dungeon section: The honest dungeon rotation is
--    pull/burst/slow, not heal/support: 1) Engage with Seeking Flame or
--    Infernal Strike
('knight-of-xoroth-hellfire', 1, 0, 'medium aoe>cast melee::Infernal Strike!88'),

-- 2. Flames of Xoroth (guide/dungeon, from level 0, ID 801059).
--    [costs 150 Wut]
--    Sidekick Hellfire, dungeon section: 3) Weave Infernal Strike/Flames of
--    Xoroth filler, dumping Demonfire via Hellmaw, Skulltaker, or Flames of
--    Xoroth for burst
('knight-of-xoroth-hellfire', 2, 0, 'medium aoe>cast melee::Flames of Xoroth!87'),

-- 3. Hellmaw (guide/dungeon, from level 0, ID 806965).
