-- ===== klasse-17-knight-of-xoroth-war.sql ================================
-- Knight of Xoroth / War - combat rotation up to level 20.
--
-- Role:      damage
-- Position:  close
-- Spec id:   18   (class default)
--
-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::knight-of-xoroth-war
--
-- STANDARD RESOURCES this rotation spends:
--   Wut: Chainwhip, Gore, Chainwhip, Gore, Meatsaw, Melt, Flames of Xoroth, Infernal Strike
--   These do NOT come from AscensionCustomResourceData.h but from the
--   standard system. Whether the class actually builds them is in
--   no data - only the bar in game shows it.
--   MIND THE TEST TARGET. Generation is read off the spell, not off
--   the damage dealt, so against a training dummy the bar stays at
--   zero and every rule that spends the resource looks broken. On
--   14.09.2026 we read a Reaper bot that way and filed it as a bug;
--   measured on a live server on 17.09.2026, 14 of 57 Reaper bots
--   had runic power, several a full bar.
--   If a rule never fires although it looks affordable: check the
--   bar on the bot against a real target first, do not change the
--   rule.
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'knight-of-xoroth-war';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Flesh Hook (guide/dungeon, from level 0, ID 500020).
--    [cooldown 35s]
--    Sidekick War, dungeon section: Peel loose adds off healers and casters
--    with Flesh Hook (pull) or Chainwhip (silence), dragging or shutting
--    them down
('knight-of-xoroth-war', 1, 0, 'medium aoe>cast melee::Flesh Hook!88'),

-- 2. Chainwhip (guide/dungeon, from level 0, ID 800081).
--    [costs 100 Wut, cooldown 20s]
--    Sidekick War, dungeon section: Peel loose adds off healers and casters
--    with Flesh Hook (pull) or Chainwhip (silence), dragging or shutting
--    them down
('knight-of-xoroth-war', 2, 0, 'medium aoe>cast melee::Chainwhip!87'),

-- 3. Gore (guide/dungeon, from level 0, ID 805555).
--    [costs 300 Wut]
--    Sidekick War, dungeon section: Sustain yourself with Gorged's
--    Gore-lifesteal rather than drawing on the healer's mana
('knight-of-xoroth-war', 3, 0, 'medium aoe>cast melee::Gore!86'),

-- 4. Unleash Pestilence (guide/solo, from level 0, ID 801002).
--    [cooldown 45s]
--    Sidekick War, solo section: Open hard pulls with Brimstone Bludgeon to
--    cleave and unleash Pestilence of Death
('knight-of-xoroth-war', 4, 0, 'buff missing::Unleash Pestilence>cast buff::Unleash Pestilence!85'),

-- 5. Flesh Hook (guide/solo, from level 0, ID 500020).
--    [cooldown 35s]
--    Sidekick War, solo section: There is no emergency defensive button, so
--    on a bad pull break line of sight or peel with Flesh Hook/Chainwhip
--    rather than reaching for a panic cooldown
