-- ===== klasse-18-guardian-gladiator.sql ==================================
-- Guardian/Gladiator PvE: https://ascensionsidekick.com/guardian, 15.09.2026.
-- Needs a matching one-hand weapon and a shield. No switch to Vanguard.
-- Ram/Glory and the reactive attacks before Pulverize; multi-target from three enemies on.
-- The PvP tools Net Throw and Spear Throw are not standing PvE fillers.
-- Source-checked, not measured in play as an optimal rotation.

-- Guardian / Gladiator - combat rotation up to level 20.
--
-- Role:      damage
-- Position:  close
-- Spec id:   19   (class default)
--
-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::guardian-gladiator
--
-- CROSS-CHECK RAISED:
--   Assault Formation derived from the spell text: not defensive, matching the dps role. The guide names none.
--   Assault Formation wins the stance; discarded: Tower Formation (5x), Line Formation (2x)
--
-- STANDARD RESOURCES this rotation spends:
--   Energie: Assault Formation, Ram, Centurion Strike, Glorious Arena, Broad Sweep, Pulverize, Glorious Arena, Standard of Spellwarding, Standard of Supremacy, Shield of Denial, Standard of Might, Standard of Valiance, Broad Sweep, Tower Formation, Standard of Recovery
--   These do NOT come from AscensionCustomResourceData.h but from the
--   standard system. Whether the class actually builds them is in
--   no data - only the bar in game shows it.
--   MIND THE TEST TARGET. Generation is read off the spell, not off
--   the damage dealt, so against a training dummy the bar stays at
--   zero and every rule that spends the resource looks broken. On
--   14.09.2026 we read a Reaper bot that way and filed it as a bug;
--   measured on a live server on 17.09.2026, 14 of 57 Reaper bots
--   had runic power, several a full bar.
--   If a rule never fires although it looks affordable: check the
--   bar on the bot against a real target first, do not change the
--   rule.
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'guardian-gladiator';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Assault Formation (Spell.dbc/stance, from level 0, ID 803417).
--    [costs 20 Energie, cooldown 1s]
--    Stance of the spec. 2 rule(s) of this rotation name it as their
--    CasterAuraSpell and are uncastable without it. Only one stance holds
--    at a time.
('guardian-gladiator', 1, 0, 'buff missing::Assault Formation>cast buff::Assault Formation!95'),

-- 2. Battle Rush (source-checked/Gladiator, from level 1, ID 802197).
--    [cooldown 30s]
--    Close the gap, not to be spammed in melee.
('guardian-gladiator', 2, 0, 'enemy out of melee>cast melee::Battle Rush!92'),

-- 3. Counter Stance (source-checked/Gladiator, from level 40, ID 501535).
