-- ===== klasse-19-templar-crusader.sql ====================================
-- Crusader: the Sidekick PvE sustain rotation, source-checked 15.09.2026.
-- Source: https://ascensionsidekick.com/templar (coaGuide/Templar/Crusader).
-- Not tested in play; nothing derived automatically from mention order.
-- A TWO-HAND WEAPON is required for Argent Blade; Sidekick recommends it for the whole kit.
-- Righteous Tempest, Chastise and Blade of Faith deliberately NOT automatic:
-- the dungeon guide says to hold oaths, not to spend them constantly.
-- Solo burst is a different strategy decision, not an unconditional fallback.
-- One libram (Grace), as a self-buff. Temple Guardian is not a self-heal routine.
-- Locally GrantOath applies: at most 10 chain stacks, and Crusader gets one oath type.
-- No three no-aura rules overwriting each other's oaths.
-- Condemn serves as the DoT here; Holy Cleave on multi-target, otherwise Righteous Lunge.
-- Transformation: Argent Blade -> Scarlet Hammer, handled by the server.
-- Replace the global strategy owner=0 only; keep per-bot rules.

-- Templar / Crusader - combat rotation up to level 20.
--
-- Role:      damage
-- Position:  close
-- Spec id:   24   (class default)
--
-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::templar-crusader
--
-- STANDARD RESOURCES this rotation spends:
--   Energie: Titanstrike, Argent Blade, Condemn, Holy Cleave, Righteous Lunge, Blade of Faith, Righteous Tempest, Divine Force, Testament of Resolve, Holy Cleave, Harmonic Disposition, Condemn, Chastise
--   These do NOT come from AscensionCustomResourceData.h but from the
--   standard system. Whether the class actually builds them is in
--   no data - only the bar in game shows it.
--   MIND THE TEST TARGET. Generation is read off the spell, not off
--   the damage dealt, so against a training dummy the bar stays at
--   zero and every rule that spends the resource looks broken. On
--   14.09.2026 we read a Reaper bot that way and filed it as a bug;
--   measured on a live server on 17.09.2026, 14 of 57 Reaper bots
--   had runic power, several a full bar.
--   If a rule never fires although it looks affordable: check the
--   bar on the bot against a real target first, do not change the
--   rule.
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'templar-crusader';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Libram of Grace (source-checked/Crusader, from level 30, ID 801463).
--    [cooldown 180s]
--    A single libram as a self-buff. Do not alternate with Consecration;
--    Grace ties damage to healing and is the one named in the PvE guide.
('templar-crusader', 1, 0, 'buff missing::Libram of Grace>cast buff::Libram of Grace!90'),

-- 2. Titanstrike (source-checked/Crusader, from level 34, ID 806521).
--    [costs 15 Energie, cooldown 8s]
--    Execute with self-healing that extends the oath chain. The native cast
--    check tests the 35% bound or the Testament release; no 20% stand-in.
('templar-crusader', 2, 0, 'can cast::Titanstrike>cast melee::Titanstrike!88'),

-- 3. Argent Blade (source-checked/Crusader, from level 13, ID 804929).
--    [costs 50 Energie, cooldown 5s]
--    Extends the oath chain and heals through damage. Keep the base spell:
--    Scarlet Training transforms the next Argent Blade, not Chastise.
('templar-crusader', 3, 0, 'can cast::Argent Blade>cast melee::Argent Blade!86'),

-- 4. Condemn (source-checked/Crusader, from level 4, ID 804906).
--    [costs 30 Energie]
--    Apply the holy DoT before the standing builders spend energy. Not
--    reapplied constantly; mind the local limit of one oath type.
('templar-crusader', 4, 0, 'debuff missing::Condemn>cast debuff::Condemn!84'),

-- 5. Holy Cleave (source-checked/Crusader, from level 12, ID 801445).
--    [costs 35 Energie]
--    Takes priority over Lunge at three or more nearby attackers. Builds
--    and holds the multi-target oath; no automatic Tempest spend.
('templar-crusader', 5, 0, 'medium aoe>cast melee::Holy Cleave!80'),

-- 6. Righteous Lunge (source-checked/Crusader, from level 1, ID 801443).
