--
-- Enable with:  co +custom::ranger-archery
--
-- STANDARD RESOURCES this rotation spends:
--   Fokus: Precision Shot, Skullpiercer, Serrated Shot, Serrated Shot, Quick Shot, Precision Shot, Skullpiercer, Neurotoxin Arrow, Deadshot, Guise, Greater Footpad's Adaptation, Brutal Shot, Greater Woodsman's Adaptation, Cutthroat, Hunting Shot, Snapseed, Feral Pressure, Rusty Shiv, Befriend Beast, Uncover Weakness, Footpad's Adaptation, Woodsman's Adaptation, Flank, Toxic Dart, Wild Strike
--   These do NOT come from AscensionCustomResourceData.h but from the
--   standard system. Whether the class actually builds them is in
--   no data - only the bar in game shows it.
--   MIND THE TEST TARGET. Generation is read off the spell, not off
--   the damage dealt, so against a training dummy the bar stays at
--   zero and every rule that spends the resource looks broken. On
--   14.09.2026 we read a Reaper bot that way and filed it as a bug;
--   measured on a live server on 17.09.2026, 14 of 57 Reaper bots
--   had runic power, several a full bar.
--   If a rule never fires although it looks affordable: check the
--   bar on the bot against a real target first, do not change the
--   rule.
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'ranger-archery';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Precision Shot (guide/dungeon, from level 0, ID 500075).
--    [costs 40 Fokus]
--    Sidekick Archery, dungeon section: 4) Run single-target priority
--    (Precision Shot dump > Skullpiercer > Serrated Shot > Deadshot
--    execute) on the designated kill target once Advantage is banked
('ranger-archery', 1, 0, 'medium aoe>cast::Precision Shot!88'),

-- 2. Skullpiercer (guide/dungeon, from level 0, ID 802036).
--    [costs 30 Fokus]
--    Sidekick Archery, dungeon section: 4) Run single-target priority
--    (Precision Shot dump > Skullpiercer > Serrated Shot > Deadshot
--    execute) on the designated kill target once Advantage is banked
('ranger-archery', 2, 0, 'medium aoe>cast::Skullpiercer!87'),

-- 3. Serrated Shot (guide/dungeon, from level 0, ID 500073).
--    [costs 25 Fokus]
