-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::cultist-heretic
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'cultist-heretic';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Void Shield (healer plan, from level 0, ID 500715).
--    Sidekick Heretic, healing priority 'Someone about to die': You have no
--    instant nuke heal - use Dark Infusion (pre-loaded, fires on the hit),
--    Dark Veil channeled on them (stacking absorb), or a pre-cast Void Sh
('cultist-heretic', 1, 0, 'party member critical health>cast buff party::Void Shield!92'),

-- 2. Malevolence (healer plan, from level 0, ID 500714).
--    Sidekick Heretic, healing priority 'Group AoE damage': Forbidden
--    Ritual (group shield) -> Satiate + Dark Matter (30-yd HoT) -> let
--    Malevolence's Black Blood cleave-heal splash.
('cultist-heretic', 2, 0, 'medium group heal setting>cast::Malevolence!91'),

-- 3. Satiate (healer plan, from level 0, ID 804275).
--    [cooldown 180s]
--    Sidekick Heretic, healing priority 'Group AoE damage': Forbidden
--    Ritual (group shield) -> Satiate + Dark Matter (30-yd HoT) -> let
--    Malevolence's Black Blood cleave-heal splash.
('cultist-heretic', 3, 0, 'medium group heal setting>cast::Satiate!90'),

-- 4. Devour Magic (healer plan, from level 0, ID 520151).
--    Sidekick Heretic, healing priority 'Harmful magic on an ally': Devour
--    Magic (dispels plus heals you); Devourer dispels an extra.
('cultist-heretic', 4, 0, 'cure party::Devour Magic>cast cure party::Devour Magic!89'),

-- 5. Eldritch Mending (healer plan, from level 0, ID 500711).
--    Sidekick Heretic, healing priority 'Sustained single-target': Gaze of
--    C'Thun (heal mode) plus Eldritch Mending, keep Entropic Host rolling.
('cultist-heretic', 5, 0, 'party member medium health>cast heal party::Eldritch Mending!88'),

-- 6. Gaze of C'Thun (healer plan, from level 0, ID 500110).
--    [cooldown 10s]
--    Sidekick Heretic, healing priority 'Sustained single-target': Gaze of
--    C'Thun (heal mode) plus Eldritch Mending, keep Entropic Host rolling.
('cultist-heretic', 6, 0, 'party member medium health>cast::Gaze of C''Thun!87'),

-- 7. Void Shield (healer plan, from level 0, ID 500715).
--    Sidekick Heretic, healing priority 'Setup before damage lands':
--    Abyssal Covenant on your most-focused ally (usually the tank); Void
--    Shield on the tank plus Forbidden Ritual to pre-shield the group
--    before a known Ao
('cultist-heretic', 7, 0, 'party member medium health>cast buff party::Void Shield!86'),

-- 8. Sanity Tap (healer plan, from level 0, ID 802575).
