-- 1. Shine (healer plan, from level 0, ID 800357).
--    Sidekick Blessings, healing priority 'Someone dropping fast': Instant
--    Daybreak, then Shine (instant if Dawn is up) - Savior makes both hit
--    harder under 20% HP.
('sun-cleric-blessings', 1, 0, 'party member critical health>cast heal party::Shine!92'),

-- 2. Dawn (healer plan, from level 0, ID 804584).
--    Sidekick Blessings, healing priority 'Someone dropping fast': Instant
