--    Illumination/Shine across the stack; cash a Dawn window to fire
--    Sunlight on the 5 low
('sun-cleric-blessings', 3, 0, 'medium group heal setting>cast heal aoe::Radiant Cascade!90'),

-- 4. Illumination (healer plan, from level 0, ID 500143).
