-- 1. Horusath Blast (guide/dungeon, from level 0, ID 500154).
--    [cooldown 25s]
--    Sidekick Valkyrie, dungeon section: In combat: keep autos and Horusath
--    Blast flowing to build Solar Power
('sun-cleric-valkyrie', 1, 0, 'medium aoe>cast melee::Horusath Blast!88'),

-- 2. Glorious Execution (guide/dungeon, from level 0, ID 800626).
--    [costs 5 Mana, cooldown 8s]
--    Sidekick Valkyrie, dungeon section: Fire Glorious Execution and
