('sun-cleric-valkyrie', 2, 0, 'medium aoe>cast melee::Glorious Execution!87'),

-- 3. Chains of Light (guide/dungeon, from level 0, ID 801524).
--    Sidekick Valkyrie, dungeon section: Chains of Light only snares, and
--    your only healing is passive: Light of the Sun's parry heal, Arbiter
--    of Light, Glorious Execution's mana refund
('sun-cleric-valkyrie', 3, 0, 'medium aoe>cast melee::Chains of Light!86'),

-- 4. Solar Prayer (guide/playstyle, from level 0, ID 806479).
