-- ===== klasse-28-tinker-nc.sql ===========================================
-- Tinker (class 28) - NON-COMBAT strategy. Written by hand.
--
-- The generator (tools/rotation_bauen.py) only produces combat rotations. The
-- two abilities here explicitly do NOT belong in combat:
--
--   Defibrillate  per its spell text cannot be cast in combat
--                 ("Cannot be cast when in combat").
--   Companions    rebuilding one costs time and quiet; in combat that would
--                 be lost damage.
--
-- Enable with:  nc +custom::tinker-nc
--
-- The combat rotation sits next to this in klasse-28-tinker.sql and places a
-- turret through `no pet`. MIND THE CONFLICT: if turret, Mechano-Bear and
-- Clockwork Assistant all count as a companion for `no pet`, the rules
-- exclude one another - whichever stands first prevents the others.
-- Unverified; it will show up immediately in a play test.
--
-- The source guide does not list Mechano-Bear and Clockwork Assistant among
-- the early actions of the Demolition spec. They stand here anyway, because
-- the class learns them by level 14 and a companion outside combat costs
-- nothing.

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'tinker-nc';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Resurrection. Highest relevance, because a dead party member makes
--    everything else worthless.
('tinker-nc', 1, 0, 'party member dead>cast rez::Defibrillate!95'),

-- 2. Rebuild the companion. Mechano-Bear from level 14, Clockwork Assistant
--    from 8 - the bot takes whichever it knows. `no pet` rather than
--    `spell ready`, because both stay "until dismissed" per their spell
--    text; driven off the cooldown the bot would resummon them constantly.
('tinker-nc', 2, 0, 'no pet>cast::Build: Mechano-Bear!80,cast::Build: Clockwork Assistant!79');

-- ===== klasse-29-venomancer-fortitude.sql ================================
-- Venomancer / Fortitude - combat rotation up to level 20.
--
-- Role:      tank
-- Position:  close
-- Spec id:   52
--
-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::venomancer-fortitude
--
-- CROSS-CHECK RAISED:
--   Beetle Form wins the stance; discarded: Spider Form (6x)
--
-- STANDARD RESOURCES this rotation spends:
--   Energie: Arachnophobia
--   Wut: Chitin Rush, Expulsion, Carapace Crash, Hivebreak, Expulsion, Chitin Rush, Carapace Crash, Hivebreak, Pinch, Venomtip Poison
--   These do NOT come from AscensionCustomResourceData.h but from the
--   standard system. Whether the class actually builds them is in
--   no data - only the bar in game shows it.
--   MIND THE TEST TARGET. Generation is read off the spell, not off
--   the damage dealt, so against a training dummy the bar stays at
--   zero and every rule that spends the resource looks broken. On
--   14.09.2026 we read a Reaper bot that way and filed it as a bug;
--   measured on a live server on 17.09.2026, 14 of 57 Reaper bots
--   had runic power, several a full bar.
--   If a rule never fires although it looks affordable: check the
--   bar on the bot against a real target first, do not change the
--   rule.
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'venomancer-fortitude';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Beetle Form (Spell.dbc/stance, from level 0, ID 803183).
--    [costs 25 Mana]
--    Stance of the spec. 14 rule(s) of this rotation name it as their
--    CasterAuraSpell and are uncastable without it. Only one stance holds
--    at a time.
('venomancer-fortitude', 1, 0, 'buff missing::Beetle Form>cast buff::Beetle Form!95'),

-- 2. Chitin Rush (guide/dungeon, from level 0, ID 803570).
