-- ===== klasse-30-reaper-harvest.sql ======================================
-- Reaper / Harvest - combat rotation up to level 20.
--
-- Role:      damage
-- Position:  close
-- Spec id:   56   (class default)
--
-- Generated by tools/rotation_bauen.py from the Sidekick spec guide,
-- checked against Spell.dbc, the class spell list and the resource
-- table. Not a measured optimum - a rotation a bot can run.
--
-- Enable with:  co +custom::reaper-harvest
--
-- STANDARD RESOURCES this rotation spends:
--   Runenmacht: Crow's Harvest, Murder, Slaughter, Crow's Harvest, Murder, Slaughter, Wraithblade, Soul Strike
--   These do NOT come from AscensionCustomResourceData.h but from the
--   standard system. Whether the class actually builds them is in
--   no data - only the bar in game shows it.
--   MIND THE TEST TARGET. Generation is read off the spell, not off
--   the damage dealt, so against a training dummy the bar stays at
--   zero and every rule that spends the resource looks broken. On
--   14.09.2026 we read a Reaper bot that way and filed it as a bug;
--   measured on a live server on 17.09.2026, 14 of 57 Reaper bots
--   had runic power, several a full bar.
--   If a rule never fires although it looks affordable: check the
--   bar on the bot against a real target first, do not change the
--   rule.
--

DELETE FROM `playerbots_custom_strategy` WHERE `name` = 'reaper-harvest';

INSERT INTO `playerbots_custom_strategy` (`name`, `idx`, `owner`, `action_line`) VALUES

-- 1. Crow's Harvest (guide/dungeon, from level 0, ID 504011).
