--    Sidekick Harvest, dungeon section: 1) Pull with Crow's Harvest into
--    the pack to tag every add, harvest Soul Fragments, and start the
--    Darkrend Scythe bleeds
('reaper-harvest', 1, 0, 'medium aoe>cast melee::Crow''s Harvest!88'),

